class Matematyka {
  static PI = 3.14159;

  static kwadrat(x) {
    return x * x;
  }
}

console.log(Matematyka.PI);         // 3.14159 - bez tworzenia instancji
console.log(Matematyka.kwadrat(5)); // 25

class Matematyka {
  static PI = 3.14159;
}

const instancja = new Matematyka();
console.log(instancja.PI);   // undefined - pole statyczne NIE istnieje na instancji
console.log(Matematyka.PI);  // 3.14159 - poprawny dostep, przez klase

class Uzytkownik {
  static licznikUtworzonych = 0;

  constructor(nazwa) {
    this.nazwa = nazwa;
    Uzytkownik.licznikUtworzonych++; // dostep do pola statycznego PRZEZ nazwe klasy
  }
}

new Uzytkownik("A");
new Uzytkownik("B");
new Uzytkownik("C");
console.log(Uzytkownik.licznikUtworzonych); // 3

