class Konwerter2 {
  static celsjuszNaKelwiny(c) {
    return c + 273.15;
  }
}

console.log(Konwerter2.celsjuszNaKelwiny(20)); // 293.15

class Produkt3 {
  static RABAT = 0.1;
  static cenaPoRabacie(cena) {
    return cena * (1 - Produkt3.RABAT);
  }
}

console.log(Produkt3.cenaPoRabacie(200)); // 180

