class Produkt3 {
  static RABAT = 0.1;
}

const produkt = new Produkt3();
console.log(produkt.RABAT); // undefined
// Pole statyczne nalezy WYLACZNIE do klasy, nie do zadnej konkretnej
// instancji - dostep mozliwy jest tylko przez nazwe klasy (Produkt3.RABAT),
// nigdy przez instancje (produkt.RABAT zawsze zwroci undefined).

class Waliduj {
  static jestEmail(tekst) {
    return tekst.includes("@");
  }
  static jestPelnoletni(wiek) {
    return wiek >= 18;
  }
}

console.log(Waliduj.jestEmail("test@test.pl")); // true
console.log(Waliduj.jestEmail("nieprawidlowy")); // false
console.log(Waliduj.jestPelnoletni(20)); // true
console.log(Waliduj.jestPelnoletni(15)); // false

class Identyfikator {
  static nastepneId = 1;
  static generuj() {
    const id = Identyfikator.nastepneId;
    Identyfikator.nastepneId++;
    return id;
  }
}

console.log(Identyfikator.generuj()); // 1
console.log(Identyfikator.generuj()); // 2
console.log(Identyfikator.generuj()); // 3

class Kolor {
  static CZERWONY = "#FF0000";
  static ZIELONY = "#00FF00";
  static NIEBIESKI = "#0000FF";
}

console.log(Kolor.CZERWONY); // "#FF0000"
console.log(Kolor.ZIELONY);  // "#00FF00"
console.log(Kolor.NIEBIESKI); // "#0000FF"

class Przyklad {
  wartosc = 42;
  metodaInstancji() {
    return this; // this === konkretna instancja, na ktorej metoda zostala wywolana
  }
  static metodaStatyczna() {
    return this; // this === sama klasa Przyklad, ZADNA instancja nie jest zwiazana
  }
}

const instancja = new Przyklad();
console.log(instancja.metodaInstancji() === instancja); // true
console.log(Przyklad.metodaStatyczna() === Przyklad);   // true
// W metodzie instancji this odnosi sie do KONKRETNEGO obiektu, na ktorym
// metoda zostala wywolana (instancja.metoda()). W metodzie statycznej
// this odnosi sie do SAMEJ KLASY, poniewaz metoda statyczna jest wywolywana
// na klasie (Klasa.metoda()), a nie na zadnej konkretnej instancji.
